async function interrupt(c:Client,r:Row,reason:string){if(r.status!=='active')return;const now=await time(c);r.status='interrupted';r.board_ids=[];r.deadline_at=null;r.state.interruptedAt=new Date(now).toISOString();r.state.recoveryDays=(await policy(c)).recoveryDays;r.state.recoverExpiresAt=new Date(now+r.state.recoveryDays*86400000).toISOString();r.revision++;await save(c,r);await c.query("update dartflow_private.play_capabilities set expires_at=$2 where session_id=$1 and purpose in('recovery','participant','controller')and(expires_at is null or expires_at>$2)",[r.id,r.state.recoverExpiresAt]);void reason;}
