async function policy(c:Client):Promise<PlayRetentionPolicy>{const p=(await c.query('select * from dartflow_private.play_retention_policy where singleton')).rows[0];return{claimDays:p.claim_days,recoveryDays:p.recovery_days,revision:p.revision};}
export async function getPlayRetentionPolicy(principal:PlayPrincipal):Promise<PlayRetentionPolicy>{if(!principal.accountId)throw new DomainError('unauthorized','Meld je aan.',401);await ownerAccess(principal.accountId);return policy(database());}
export async function getPlaySession(principal:PlayPrincipal,id:string):Promise<PlaySessionView>{const c=database(),r=await row(c,id),cap=await readCap(c,principal.token);if(cap?.purpose==='claim'&&cap.session_id===r.id){if(cap.revoked_at||!cap.expires_at||cap.expires_at.getTime()<=await time(c)||r.status!=='completed')throw new DomainError('play_claim_expired','Deze privéclaim is verlopen of niet beschikbaar.',410);const a:Access={key:`cap:${cap.id}`,cap,participantId:cap.participant_id,manage:false,write:false,expired:false},result=await view(c,r,a);result.participants=result.participants.map(({accountId:_,...p})=>{void _;return p;});result.permissions=Object.fromEntries(Object.entries(result.permissions).map(([key,value])=>[key,key==='canClaim'&&value]))as PlaySessionView['permissions'];return result;}const a=await access(c,r,principal);return view(c,r,a);}
export async function getMyPlaySessions(accountId:string):Promise<{sessions:PlaySessionView[];history:PlaySessionView[]}>{uuid(accountId);await assertAccountActive(accountId);const c=database(),rows=(await c.query<Row>("select * from dartflow_private.play_sessions where owner_account_id=$1 or exists(select 1 from jsonb_array_elements(state->'participants')p where p->>'accountId'=$1::text or p->>'claimedBy'=$1::text)order by updated_at desc limit 100",[accountId])).rows,values=await Promise.all(rows.map(async r=>view(c,r,await access(c,r,{accountId}))));return{sessions:values.filter(v=>v.status!=='completed'),history:values.filter(v=>v.status==='completed')};}
