export async function getPublicPlayBoard(boardId:string,client:Client=database()):Promise<PublicPlaySession|undefined>{const r=(await client.query<Row>("select * from dartflow_private.play_sessions where $1=any(board_ids)and status in('active','completed')order by created_at desc limit 1",[uuid(boardId)])).rows[0];if(r)return publicPlay(client,r,`board-${boardId}`);}
