export async function getPlayBoard(boardId:string,principal:PlayPrincipal={}):Promise<PlayBoardView>{const c=database(),b=(await c.query<{name:string;blocked:boolean;access:string|null}>('select b.name,b.blocked,cb.access from dartflow_private.boards b left join dartflow_private.club_boards cb on cb.board_id=b.id where b.id=$1',[uuid(boardId)])).rows[0];if(!b)throw new DomainError('not_found','Deze baan bestaat niet.',404);const play=await getPublicPlayBoard(boardId,c);let error:DomainError|undefined;try{await transaction(client=>board(client,boardId,principal));}catch(e){if(!(e instanceof DomainError))throw e;error=e;}const official=(await c.query<{id:string}>("select m.id from dartflow_private.matches m where m.board_id=$1 and not exists(select 1 from dartflow_private.platform_match_links l join dartflow_private.platform_entities e on e.id=l.entity_id where l.match_id=m.id and e.kind='lobby')limit 1",[boardId])).rows[0];return{...(official?{officialUrl:`/wedstrijd/${official.id}`}:{ }),board:{id:boardId,name:b.name,available:!error,status:!error?'available':error.code==='board_closed'?'closed':error.code.includes('reserved')?'reserved':'occupied',...(error?{reason:error.message}:{})},canStart:!error,requiresAccount:error?.code==='play_login_required',...(play?{play}:{})};}
